      ro: ["1700 este anul începerii reconstrucției bisericii actuale", "1736 reprezintă anul sfințirii edificiului baroc", "47 metri este înălțimea turnului alb al clopotniței", "1559 a fost anul fondării ordinului Mercedar în Quito", "18 secolul detaliilor arhitecturale în stil Mudéjar", "22 de picturi de Victor Mideros sunt expuse în interior"],
      en: ["1700 marks the start of reconstruction for the current church", "1736 was the year the Baroque structure was consecrated", "47 meters is the height of the distinctive white bell tower", "1559 was when the Mercedarian Order was established in Quito", "18th century Moorish carvings decorate the interior ceilings", "22 paintings by Victor Mideros are housed within the church"],
      es: ["En 1700 comenzó la reconstrucción de la iglesia actual", "En 1736 se consagró el edificio barroco", "La torre campanario blanca mide 47 metros de altura", "En 1559 se fundó la Orden de la Merced en Quito", "Las tallas mudéjares datan del siglo XVIII", "En el interior se encuentran 22 pinturas de Víctor Mideros"],
      pt: ["Em 1700, iniciou-se a reconstrução da igreja atual", "Em 1736, o edifício barroco foi consagrado", "A torre sineira branca mede 47 metros de altura", "Em 1559, a Ordem Mercedária foi fundada em Quito", "As talhas mudéjares datam do século XVIII", "No interior encontram-se 22 pinturas de Victor Mideros"],
