      en: ["1580 was the year the hacienda was officially founded", "1736 was when the French Geodesic Mission stayed at the estate", "100 hectares make up the core historical area", "1580 is the construction date of the still-active chapel", "450 years of history make it the oldest hacienda in the country", "1990 was when it began operating as a historical boutique hotel"],
