      hu: ["Az építkezés 1557-ben kezdődött", "1736-ban geodéziai mérőpont volt", "1999 óta vallási művészeti múzeum", "1999-ben lett az UNESCO világörökség része", "Kőből és téglából épült", "Történelmi sípnegyedes orgonát őriz"],
      ro: ["Începerea construcției în anul 1557", "Punct de referință geodezic în 1736", "Muzeu de artă religioasă din 1999", "Parte a patrimoniului UNESCO din 1999", "Construită din piatră și cărămidă", "Găzduiește o orgă istorică valoroasă"],
      en: ["Construction started in 1557", "Reference point for Geodesic Mission in 1736", "Museum of Religious Art since 1999", "UNESCO World Heritage site since 1999", "Built using stone and brick", "Houses a historic pipe organ"],
