      pt: ["Início da construção em 1557", "Ponto de referência da Missão Geodésica em 1736", "Museu de arte religiosa desde 1999", "Parte do Património Mundial da UNESCO desde 1999", "Construída em pedra e tijolo", "Abriga um órgão histórico"],
      fr: ["Début de la construction en 1557", "Point de référence de la mission géodésique en 1736", "Musée d'art religieux depuis 1999", "Inscrite au patrimoine mondial de l'UNESCO depuis 1999", "Construite en pierre et en brique", "Abrite un orgue historique"],
