      es: ["Fue construida en el siglo XVI por monjes dominicos.", "Una obra maestra de la Escuela Quiteña de arte."],
      pt: ["Foi construída no século XVI por monges dominicanos.", "Uma obra-prima da Escola de Arte de Quito."],
