    facts: {
      de: ["Das Treffen fand 1822 statt.", "Die Generäle planten hier die endgültige Befreiung Südamerikas."],
      hu: ["A találkozóra 1822-ben került sor.", "A tábornokok itt tervezték meg Dél-Amerika végső felszabadítását."],
      ro: ["Întâlnirea a avut loc în 1822.", "Generalii au plănuit aici eliberarea finală a Americii de Sud."],
      en: ["The meeting took place in 1822.", "The generals planned the final liberation of South America here."],
      es: ["El encuentro tuvo lugar en 1822.", "Los generales planearon aquí la liberación definitiva de América del Sur."],
      pt: ["O encontro teve lugar em 1822.", "Os generais planearam aqui a libertação definitiva da América do Sul."],
      fr: ["La rencontre a eu lieu en 1822.", "Les généraux y ont planifié la libération définitive de l'Amérique du Sud."],
    }, image: "/poi-images/la-rotonda-history-v2.webp",
    descriptionAdvanced: {
      de: "La Rotonda, offiziell als Hemiciclo de la Rotonda bekannt, ist eines der symbolträchtigsten Denkmäler in Guayaquil, Ecuador. Es erinnert an das historische Treffen zwischen den beiden großen Befreiern Südamerikas, Simón Bolívar und José de San Martín, am 26. Juli 1822. Dieses Treffen, bekannt als die Konferenz von Guayaquil, war entscheidend für den weiteren Verlauf der Unabhängigkeitskriege gegen Spanien. Das Denkmal befindet sich am Malecón 2000 am Ufer des Guayas-Flusses und wurde im Jahr 1937 eingeweiht. Entworfen wurde es vom spanischen Architekten Augusto Mistretta. Die Struktur besteht aus einer halbkreisförmigen Kolonnade mit den bronzenen Statuen der beiden Generäle in der Mitte. Die zehn Säulen des Denkmals symbolisieren die Provinzen Ecuadors zur Zeit der Errichtung. Es ist ein Ort von großer nationaler Bedeutung und ein fester Bestandteil jeder Stadtbesichtigung. Die umliegenden Gärten und die Aussicht auf den Fluss machen es zu einem beliebten Treffpunkt für Einheimische und Touristen gleichermaßen.",
      hu: "A La Rotonda, hivatalos nevén Hemiciclo de la Rotonda, Guayaquil egyik legjellegzetesebb emlékműve Ecuadornak. Az emlékmű Dél-Amerika két nagy felszabadítója, Simón Bolívar és José de San Martín 1822. július 26-i történelmi találkozójának állít emléket. Ez a guayaquili konferenciaként ismert esemény döntő fontosságú volt a Spanyolország elleni függetlenségi háborúk kimenetele szempontjából. Az emlékmű a Malecón 2000 sétányon, a Guayas folyó partján található, és 1937-ben avatták fel. Tervezője Augusto Mistretta spanyol építész volt. A szerkezet egy félkör alakú oszlopsorból áll, amelynek közepén a két generális bronzszobra látható. Az emlékmű tíz oszlopa az építés idején meglévő ecuadori tartományokat jelképezi. Ez a helyszín hatalmas nemzeti jelentőséggel bír, és minden városnéző túra elmaradhatatlan állomása. A környező kertek és a folyóra nyíló kilátás népszerű találkozóhellyé teszi a helyiek és a turisták számára egyaránt.",
      ro: "La Rotonda, cunoscut oficial sub numele de Hemiciclo de la Rotonda, este unul dintre cele mai emblematice monumente din Guayaquil, Ecuador. Acesta comemorează întâlnirea istorică dintre cei doi mari eliberatori ai Americii de Sud, Simón Bolívar și José de San Martín, la 26 iulie 1822. Această întâlnire, cunoscută sub numele de Conferința de la Guayaquil, a fost decisivă pentru cursul ulterior al războaielor de independență împotriva Spaniei. Monumentul este situat pe Malecón 2000, pe malul râului Guayas, și a fost inaugurat în anul 1937. A fost proiectat de arhitectul spaniol Augusto Mistretta. Structura constă dintr-o colonadă semicirculară cu statuile de bronz ale celor doi generali în centru. Cele zece coloane ale monumentului simbolizează provinciile Ecuadorului la momentul ridicării sale. Este un loc de o mare importanță națională și o parte esențială a oricărui tur al orașului. Grădinile din jur și vederea spre râu îl fac un loc de întâlnire popular atât pentru localnici, cât și pentru turiști.",
      en: "La Rotonda, officially known as the Hemiciclo de la Rotonda, is one of the most iconic monuments in Guayaquil, Ecuador. It commemorates the historic meeting between the two great liberators of South America, Simón Bolívar and José de San Martín, on July 26, 1822. This meeting, known as the Guayaquil Conference, was pivotal for the future course of the wars of independence against Spain. The monument is located on the Malecón 2000 along the banks of the Guayas River and was inaugurated in 1937. It was designed by the Spanish architect Augusto Mistretta. The structure consists of a semicircular colonnade with bronze statues of the two generals at the center. The ten columns of the monument symbolize the provinces of Ecuador at the time of its construction. It is a site of immense national pride and an essential stop for any visitor to the city. The surrounding gardens and river views make it a popular meeting spot for residents and tourists alike.",
      es: "La Rotonda, conocida oficialmente como el Hemiciclo de la Rotonda, es uno de los monumentos más simbólicos de Guayaquil, Ecuador. Conmemora el histórico encuentro entre los dos grandes libertadores de América del Sur, Simón Bolívar y José de San Martín, el 26 de julio de 1822. Este encuentro, conocido como la Entrevista de Guayaquil, fue decisivo para el curso posterior de las guerras de independencia contra España. El monumento se encuentra en el Malecón 2000 a orillas del río Guayas y fue inaugurado en 1937. Fue diseñado por el arquitecto español Augusto Mistretta. La estructura consiste en una columnata semicircular con las estatuas de bronce de los dos generales en el centro. Las diez columnas del monumento simbolizan las provincias de Ecuador en el momento de su construcción. Es un lugar de gran importancia nacional y parte esencial de cualquier recorrido por la ciudad.",
      pt: "La Rotonda, oficialmente conhecida como o Hemiciclo de la Rotonda, é um dos monumentos mais simbólicos de Guayaquil, no Equador. Comemora o encontro histórico entre os dois grandes libertadores da América do Sul, Simón Bolívar e José de San Martín, a 26 de julho de 1822. Este encontro, conhecido como a Conferência de Guayaquil, foi decisivo para o curso posterior das guerras de independência contra a Espanha. O monumento situa-se no Malecón 2000, nas margens do rio Guayas, e foi inaugurado em 1937. Foi desenhado pelo arquiteto espanhol Augusto Mistretta. A estrutura consiste numa colunata semicircular com as estátuas de bronze dos dois generais no centro. As dez colunas do monumento simbolizam as províncias do Equador na altura da sua construção. É um local de grande importância nacional e parte essencial de qualquer visita à cidade.",
      fr: "La Rotonda, officiellement connue sous le nom de Hemiciclo de la Rotonda, est l'un des monuments les plus emblématiques de Guayaquil, en Équateur. Il commémore la rencontre historique entre les deux grands libérateurs de l'Amérique du Sud, Simón Bolívar et José de San Martín, le 26 juillet 1822. Cette rencontre, connue sous le nom de Conférence de Guayaquil, a été décisive pour la suite des guerres d'indépendance contre l'Espagne. Le monument est situé sur le Malecón 2000 au bord du fleuve Guayas et a été inauguré en 1937. Il a été conçu par l'architecte espagnol Augusto Mistretta. La structure consiste en une colonnade semi-circulaire avec les statues en bronze des deux généraux au centre. Les dix colonnes du monument symbolisent les provinces de l'Équateur à l'époque de sa construction. C'est un lieu de grande importance nationale et une étape incontournable de toute visite de la ville.",
    },
